import{_ as n,o as r,c as t,a3 as a}from"./chunks/framework.z_KJ15Ep.js";const l="/bilder/unterricht-kataloge/kataloge-lernplattformen-01.png",m=JSON.parse('{"title":"Lernplattformen im Katalog anlegen","description":"","frontmatter":{"title":"Lernplattformen im Katalog anlegen","source_pageid":590,"source_revision":5459},"headers":[],"relativePath":"schild3/unterricht-kataloge/lernplattformen-schulbezogene-kataloge.md","filePath":"schild3/unterricht-kataloge/lernplattformen-schulbezogene-kataloge.md"}'),i={name:"schild3/unterricht-kataloge/lernplattformen-schulbezogene-kataloge.md"};function o(s,e,g,d,p,u){return r(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="lernplattformen-im-katalog-anlegen" tabindex="-1">Lernplattformen im Katalog anlegen <a class="header-anchor" href="#lernplattformen-im-katalog-anlegen" aria-label="Permalink to &quot;Lernplattformen im Katalog anlegen&quot;">​</a></h1><p>Definieren Sie die verwendeten Lernplattformen und entscheiden Sie über deren Zuordnung. Die zugehörigen Einwilligungen werden bei Schülerinnen, Schülern und Lehrkräften dokumentiert.</p><p>Hier können die von der Schule verwendeten <strong>Lernplattformen</strong> verwaltet werden. Diese Angaben erhalten Relevanz, wenn die Einwilligungen für diese Lernplattformen für die Schülerinnen und Schüler und die Lehrkräfte dokumentiert werden.</p><p>Die Erfassung der <strong>Einwilligungen</strong> geschieht über den entsprechenden Reiter unter <em>Lehrkräfte</em> beziehungsweise unter <em>Schüler</em>.</p><h2 id="anlegen-neuer-lernplattformen" tabindex="-1">Anlegen neuer Lernplattformen <a class="header-anchor" href="#anlegen-neuer-lernplattformen" aria-label="Permalink to &quot;Anlegen neuer Lernplattformen&quot;">​</a></h2><p><a href="/bilder/unterricht-kataloge/kataloge-lernplattformen-01.png"><img src="'+l+'" alt="Übersicht über das Fenster Kataloge ➜ Lernplattformen." loading="lazy"></a></p><p><em>Übersicht über das Fenster Kataloge ➜ Lernplattformen.</em></p><p>Durch Klick auf das <strong>+</strong> kann eine neue Lernplattform angelegt werden.</p><p>In der Spalte <strong>Bezeichnung</strong> wird die entsprechende Bezeichnung eingetragen.</p><p>Durch Klick auf den Haken in der oberen Bedienfeldleiste wird die Eingabe bestätigt. Es erfolgt eine Abfrage, ob die neu angelegte Lernplattform direkt bei allen Schülerinnen und Schülern eingetragen werden soll. Dies ist insofern sinnvoll, da in den meisten Fällen die gesamte Schule diese Lernplattform nutzen soll.</p><p>Im folgenden Fenster können Sie <strong>Abgefragt</strong> und <strong>Zustimmung</strong> getrennt dokumentieren. Setzen Sie Zustimmung nur für Personen mit entsprechendem Nachweis. Das Anlegen oder Zuweisen der Lernplattform ist selbst keine Einwilligung.</p><p>Hier kann auch, wie im Beispiel, ausgewählt werden, dass keine Veränderung der Einwilligung stattfinden soll.</p><p>Dieser Schritt kann auch später mit denselben Optionen in Form eines <strong>Gruppenprozesses</strong> durchgeführt werden.</p><p>Der Katalog <strong>Lernplattformen</strong> bietet keine benutzerdefinierte Sortierung.</p><h2 id="bearbeiten-von-lernplattformen" tabindex="-1">Bearbeiten von Lernplattformen <a class="header-anchor" href="#bearbeiten-von-lernplattformen" aria-label="Permalink to &quot;Bearbeiten von Lernplattformen&quot;">​</a></h2><p>Durch einen Doppelklick in das entsprechende Feld in der Spalte &quot;Bezeichnung&quot; kann die Bezeichnung bereits angelegter Lernplattformen geändert werden.</p><p>Ein Klick auf das <strong>-</strong> löscht die angelegte Lernplattform nach Bestätigung einer Dialogabfrage.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Lernplattformen_(Schulbezogene_Kataloge)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5459.</p>',19)])])}const c=n(i,[["render",o]]);export{m as __pageData,c as default};
